                df.columns = ['code', 'entrust_bs', 'futures_direction', 'amount', 'business', 'time']
                df = df.set_index('code')
                code_list = list(set(list(df.index)))
                for code in code_list:
                    daily_init_positions = self.daily_init_positions.get(code)
                    if daily_init_positions is not None:
                        long_hold_amount = daily_init_positions.get('long_hold_amount', 0)
                        short_hold_amount = daily_init_positions.get('short_hold_amount', 0)
                        long_hold_value = daily_init_positions.get('long_hold_value', 0)
                        short_hold_value = daily_init_positions.get('short_hold_value', 0)
                    else:
                        long_hold_amount = 0
                        short_hold_amount = 0
                        long_hold_value = 0
                        short_hold_value = 0
                    df3 = df[(df['entrust_bs'] == '买') & (df['futures_direction'] == '开仓')]
                    df4 = df['futures_direction'] == '平仓'
                    df_long = pd.concat([df3, df4])
                    if not df_long.empty:
                        date = df_long.head(1)['time'][0][:10]
