    def get_TradeMode_trade_statistic(self, df_base):
        df_base['amount2'] = 0
        df_base['amount2'] = df_base.apply(lambda x: -x['amount'] if x['futures_direction'] == '平仓' else x['amount'], axis=1)
        df_base['business2'] = 0
        df_base['business2'] = df_base.apply(lambda x: -x['business'] if x['futures_direction'] == '平仓' else x['business'], axis=1)
        df_base['amount_sum'] = df_base['amount2'].cumsum(axis=0)
        df_base['business_sum'] = df_base['business2'].cumsum(axis=0)
        dif_sum = 0
        win_time = 0
        lost_time = 0
        profit = 0
        loss = 0
        for i in range(len(df_base)):
            if df_base['amount'].iloc[i] == 0:
                continue
            elif df_base['amount_sum'].iloc[i] == 0:
                if df_base['type'].iloc[i] == 'long':
                    real_profit = -df_base['business_sum'].iloc[i] - dif_sum
                else:
                    real_profit = df_base['business_sum'].iloc[i] - dif_sum
                dif_sum += real_profit
                if real_profit > 0:
                    win_time += 1
                    profit += real_profit
                    continue
                loss += real_profit
                lost_time += 1
        else:
            self.TradeMode_trade_statistic['win_time'] += win_time
            self.TradeMode_trade_statistic['lost_time'] += lost_time
            self.TradeMode_trade_statistic['total_time'] += win_time
            self.TradeMode_trade_statistic['total_time'] += lost_time
            self.TradeMode_trade_statistic['profit'] += profit
            self.TradeMode_trade_statistic['loss'] += loss
            return None
    def cleanup(self, code, exception=None):
        if self.config.strategy.run_type == RunType.BACKTEST:
            self._stop_save_csv_thread = True
            if self.sync_save_testds_to_csv.is_alive():
                system_log.debug('更新回测信息线程正在运行，等待线程结束')
                start_time = time.time()
                self.sync_save_testds_to_csv.join()
                system_log.debug('更新回测信息线程已正常结束，耗时：{}s'.format(time.time() - start_time))
            else:
                system_log.debug('更新回测信息线程已结束')
        self.clear_data()
    def interface(self):
        return self
